// Proactive English B2 · Syria Edition · Book 2 · Unit 16 — Answer Key
const L = require('./lib');
const { p, h1, h2, pb, sp, box, table, C } = L;
const out = [];
const S = (t) => p(t, { bold: true, color: C.teal, before: 160, after: 60 });
const A = (t) => p(t, { indent: 200, after: 50 });
const SAMPLE = (paras) => box('Sample answer', paras, 'FFFFFF', C.navy);
const NOTE = (t) => box('Note', [t], C.lyellow, C.orange);

out.push(h1('Unit 16  Judging Against Criteria — Answer Key'));
out.push(p('_Proactive English · B2 · Book 2 · Syria Edition · Answer Key_', { color: '7F7F7F' }));
out.push(box('How to use this key', [
  'Every task has an answer or a **full sample**, including brainstorms, free speaking, reports, peer-review slips and homework.',
  '⚠ **Ask the class to bring one set of criteria** — **one they have been assessed against, or one they have written.** **A mark scheme, a tender specification, an appraisal form, a job description, a grant form.** **Anything with a list on it that somebody passed or failed.** **16.1 runs on it.**',
  '**This is the first unit of the book written from behind the desk, and the class should be told that plainly.** ⚠ **Everything in it makes the student\'s own work harder to do and easier to defend.** **A criterion that can be failed can be failed by somebody you wanted to pass** — **and that is not a flaw in the method; it is the method.**',
  '**Mrs Nasser carries 16.1 and the cost is hers.** ⚠ **Three words on an observation form, a year not knowing what she had failed, about forty lessons she would not otherwise have taught.** **Her assessor was not withholding anything** — **and the key insists on that, because a class that hears this as a story about an unkind assessor will draw the wrong conclusion and write kinder criteria rather than failable ones.**',
  '**16.7 carries the examination papers.** **Reading and Use of English Part 4** is key-word transformations, **Writing Part 2** is a review — **of an instrument rather than a product** — and **Listening Part 4** is multiple choice.',
  '⚠ **And one thing to plant now for Unit 24.** **This unit is the last place in the book where the class is given an instrument and asked to criticise it.** **24.3 asks them to do the same to themselves** — **the _cannot yet_ list at B2, with a date and a place on every item** — **and the students who do 16.5 honestly find 24.3 much easier.**',
], C.lblue, C.navy));

// ===================== 16.1 =====================
out.push(pb());
out.push(h2('16.1  Three things that can be failed'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. ⚠ **The two numbers are the cycle and they must both be said aloud.** **In most rooms the second is about half the first**, and the half that cannot be failed is not evenly spread: **it clusters at the top of the page, where the lines about character are.** **Put four pairs on the board before anything is explained.**'));
out.push(A('**b** Can be failed: **2** and **4**. Not: **1**, **3** and **5**. ⚠ **5 is the one to read out slowly** — _a flexible approach_ — **because every student in the room has written it or been judged by it**, and nobody can say what would fail it.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** — **whether the person being judged could read it and know they had failed** — and an unfailable criterion is **a reserve power.**'));
out.push(A('**b** **1** _Range demonstrated._ ⚠ **Three words on an observation form in November of her first year, and she did not understand them until the following December.**   **2** ⚠ **He uses them as a reserve power**: **if a panel has decided against somebody for a reason it would rather not write down, it reaches for the line that cannot be failed** — **and the line is on the page precisely so that it can be reached for.** **He has watched it done twice and done it once.**'));
out.push(NOTE('⚠ **The whole unit depends on the class not hearing 16.1 as a story about an unkind assessor, so say the opposite early and twice.** **Mrs Nasser\'s assessor was not withholding anything: there was nothing to withhold.** **The line could not be failed and it could not be passed either.** ⚠ **A class that hears unkindness will write kinder criteria** — _we recognise that everybody develops at their own pace_ — **which are unfailable in a warmer voice and cost the next candidate the same year.** **The cure for an unfailable criterion is a failable one, not a gentler one.**'));
out.push(NOTE('**Mr Barghouti\'s admission is the finding and it should be given his words.** ⚠ **About half the lines on any page he has drafted cannot be failed, and they are a reserve power.** **He has watched that used twice and used it once** — **and the room should sit with the arithmetic rather than with the confession.** ⚠ **The honest version of the same need is to write the real reason as a criterion before you need it**: **if what you care about is whether somebody finishes things, write _three of the last five returns complete and on the published date_**, which can be failed by the assessor as well as by the candidate. **That symmetry is the point and it is what students resist.**'));
out.push(S('Language box · Practise'));
out.push(SAMPLE([
  '**1** _(finishing things)_ _Three of the last five quarterly returns submitted complete and on the published date._',
  '**2** _(accuracy)_ _No more than two figures corrected after publication in the last four issues._',
  '**3** _(working with others)_ _At least two pieces of work in the last year signed jointly, with the other person named._',
  '**4** _(one I would fail myself)_ ⚠ _Four site visits a month, with a written note on each._ **I managed three in March and two in April.**',
  '**5** _(unfailable, with the honest version)_ ⚠ _A commitment to quality_ → _no more than two rejected consignments in a quarter._',
]));
out.push(A('⚠ Mark these on **one question and nothing else: could the person being judged read it and know whether they had failed?** Item **4** is the one to collect from everybody: **make each student produce a criterion they would fail themselves**, and about a third will find they cannot write one — **which means their three criteria are all set below their own performance and are therefore measuring nothing about them.** Item **5** is the repair and the room should do several: ⚠ **the honest version is always more specific and always shorter.**'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**A** Excellent communication skills.',
  '**B** **Failable: no.** **What it is probably after:** whether somebody can write a page a stranger can act on. **Honest version:** _one page sent in the last quarter that a reader outside the section acted on without asking a question._',
  '**A** _(the ⚠ row)_ Three of the last five returns complete and on the published date.',
  '**B** ⚠ **Failable as it stands.** **A candidate can go and count it tonight.**',
]));
out.push(S('Stage 3R · Perform – listener task'));
out.push(A('For each line, failable or not, and the honest version. ⚠ **The four rows marked ⚠ can be failed as they stand, and every one has a number in it** — **which is not a coincidence and is not a rule either.** **Make that distinction explicitly**, because half the room will conclude that a criterion needs a number: **_at least two record systems used in the last three years_ is failable and the number is doing nothing** — **what makes it failable is that a third person could check it.**'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**a** _**Marked:** six of eleven lines cannot be failed. **Three honest versions:** (1) _one page in the last quarter acted on by a reader outside the section._ (2) _two of the last three briefings delivered on the published date._ (3) _no more than one figure corrected after circulation in the last four issues.__',
  '**b** _**Partner, reading as the candidate:** all three could be counted tonight._ ⚠ _**And the hard question: would any fail somebody I would want to appoint?** **Yes — the third would fail the best sub-editor I know**, who corrects figures after circulation because he checks them again, which is the behaviour I actually want. **So the third is wrong and I shall rewrite it.**_',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Hiba gave the criterion that cost her a year: range demonstrated — three words on an observation form in November of her first year, and she spent a year not knowing what she had failed. What she did with the year was teach differently every time she was watched, in case it was the thing she was not doing: about forty lessons, none of them the lesson she would have taught, and at the end of it nobody could tell her whether any of them had range in it. Which is the cost of an unfailable criterion, and it is not borne by the assessor. The test is one question: could the person being judged read this and know whether they had failed? Omar asked whether she could have, and she said no — and neither could the assessor, which she did not understand until much later. The assessor was not withholding anything, because there was nothing to withhold. Adnan, who writes these, said about half the lines on any page he has drafted cannot be failed, and he can say exactly what they are for: they are a reserve power. If a panel has decided against somebody for a reason it would rather not write down, it reaches for the line that cannot be failed, and the line is on the page precisely so that it can be reached for — he has watched that twice and done it once. Dima asked about the honest version of the same need, and it is to write the real reason as a criterion before you need it: if what you care about is whether somebody finishes things, write three of the last five returns complete and on the published date, which can be failed by the assessor as well as by them. Rim said that is the part people do not like, and that is the whole of it: a criterion that can be failed can be failed by somebody you wanted to pass, and the discipline is to publish it anyway. A list you can escape from is not a list; it is a decision you have not taken yet. Bassel asked how many there should be, and three, in most things — three criteria that can be failed will do more work than eleven that cannot, and eleven is what most pages have. If you have eleven, nine are decoration and two are deciding. And Mazen asked how you check your own, and you read each one aloud as the person being judged by it, not as the author: in the candidate\'s voice a real criterion is a thing they can go and count tonight, and a commitment to quality in the candidate\'s voice is a silence.']));
out.push(A('Listener task: the partner\'s three criteria and whether any would fail somebody they wanted to appoint. ⚠ **Collect the answers to the second half.** **A student whose three criteria would fail nobody they value has not written criteria; they have written a description of the people they already like.** **And a student who finds that one of their three would fail the best person they know has found the most useful thing in the cycle** — **the criterion is wrong and the discovery cost them a lesson rather than an appointment.**'));
out.push(S('Board clinic – typical mistakes'));
out.push(A('**✗** _A commitment to quality._ → **✓** could it be failed?   **✗** _Excellent communication skills._ → **✓** one page, acted on, in a quarter.   **✗** Writing a kinder criterion. → **✓** a failable one, not a gentler one.   **✗** Eleven criteria. → **✓** three.   **✗** Assuming a criterion needs a number. → **✓** it needs a thing a third person could check.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** **She taught differently every time she was watched** — ⚠ **about forty lessons, none of them the lesson she would have taught.** **About sixty hours of preparation on the guesses**, and — much worse — **a first year in which she was not teaching her own lessons.**'));
out.push(A('**2** ⚠ **Whether a new teacher can do more than one thing.** **Which is reasonable and can be written down:** _at least three different task types used across four observed lessons, with the aim of each stated in the plan._ **That can be failed, and it can be failed by her.**'));
out.push(A('**3** ⚠ **Because it commits the assessor**: **if the candidate produces four plans with three task types and the aims stated, the assessor has to pass them on that criterion whether or not they think the candidate is any good.** **And she will put one sentence at the bottom:** _if you have met all three and I am still not recommending you, I shall tell you what the fourth thing is and write it down._'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**FLUENT ENGLISH** · J. Attar · 8 March · _for whoever next writes a forum moderator advertisement_',
  '**I was turned down for a moderator post in 2023 on a line that said _fluent English_, and I wrote part of that advertisement myself the year before.** ⚠ **This is not a complaint about the panel.**',
  '**What I thought it measured.** Whether somebody can handle a thread in English without the thread becoming about the English.',
  '**What it actually measures.** ⚠ **Whatever the reader thinks fluent means**, which in my case was an accent on a telephone call. **Two of the four panel members had not read anything I had written.**',
  '**What it cost.** **Two months of not applying for anything else**, and a year of thinking the problem was my English rather than a line on a page.',
  '**The failable version.** ⚠ _Four threads moderated in the last year, with the number of posts in each and one example of a disagreement you closed._ **It can be failed by me.**',
  '**And the sentence I shall put on the next advertisement.** ⚠ _If you meet all three of these and we do not appoint you, we shall tell you what the fourth thing was._',
]));
out.push(S('Stage 7 · Write freely (sample, 215 words)'));
out.push(SAMPLE([
  '**RANGE DEMONSTRATED** · H. Nasser · 6 March · _written for the person who assesses my first-year staff_',
  '**I was given three words on a form in November of my first year and I did not understand them until the following December.** ⚠ **This is not a complaint about the assessor.** **I now believe she could not have explained them either**, and that is a worse problem and a fixable one.',
  '**What I did with the year.** **I taught differently every time I was watched.** ⚠ **About forty lessons, none of them the lesson I would have taught**, each aimed at a different guess about what _range_ might mean. **Nobody ever said which guess was right, because there was no right guess to name.**',
  '**What it cost.** ⚠ **About sixty hours of preparation on the guesses**, and — much worse — **a first year in which I was not teaching my own lessons.** **The students got forty experiments and I got no information.**',
  '**What it was trying to measure.** Whether a new teacher can do more than one thing. ⚠ **Which can be written down:** _at least three different task types across four observed lessons, with the aim of each stated in the plan._ **That can be failed. It can be failed by me.**',
  '**Why nobody writes that version.** ⚠ **Because it commits the assessor.** **_Range demonstrated_ keeps the decision where it was: with the assessor, undisclosed, and unarguable.**',
]));
out.push(A('**215 words, the assessor protected in the second sentence, the cost in hours with the costless one after it, a failable version that would fail the writer, and her own page at the end.** ⚠ **The sentence that earns the band is _I now believe she could not have explained them either_**, because it converts a grievance into a design fault — **and everything the page proposes follows from that and from nothing else.**'));
out.push(S('Stage 7P · Respond (sample slip — band 2)'));
out.push(SAMPLE([
  '**Criterion: a failable version that could fail you.** _"That can be failed. It can be failed by me."_ ⚠ **Both halves, and the second is the one I had left out.** **Mine proposed a criterion I comfortably meet**, which I now see is the same fault in a different coat.',
  '**One thing to keep, and why it works.** _"The students got forty experiments and I got no information."_ **It names a cost that fell on people who were not party to any of it**, and it is the sentence I shall remember.',
  '**Ranking of the slip I was given.** **1** the failable version that fails the writer **2** the assessor protected **3** the cost in hours _(clear, and the easiest of the three)_.',
]));
out.push(S('Stage 7R · Share'));
out.push(A('⚠ **The reading is the test and it takes four seconds a line.** **In the candidate\'s voice a real criterion is a thing they can go and count tonight; an unfailable one is a silence**, and the room hears the silence without being told what it is listening for. **Do it for every student\'s three** — **it is quick, and a student who hears their own criterion produce a silence does not argue about it.** **Finish on Mrs Nasser\'s line: there was nothing to withhold.**'));
out.push(S('Homework (sample)'));
out.push(SAMPLE([
  '_**The page I brought: eleven lines, five of which can be failed.** **Fraction written at the top: 5/11.**_',
  '⚠ _**And where the six are:** four of them are in the first five lines, under _the person we are looking for_. **The failable ones start at line six, under _the work_.**_',
  '_**Which I think is the whole page in one observation:** the part about the person cannot be failed and the part about the work can._',
]));

// ===================== 16.2 =====================
out.push(pb());
out.push(h2('16.2  Weighting, in public'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. ⚠ **The question to collect is the second one, not the first.** **Most students find they have one criterion that decides everything and two that have never decided anything** — **which is a weighting of roughly _all, nothing, nothing_, unpublished.** **Put three of those on the board before the dialogue.**'));
out.push(A('**b** Weightings: **2** _(a proportion)_ and **4** _(a threshold)_. Not weightings: **1**, **3** and **5**. ⚠ **3 is the one that fools the room** — _we attach particular importance to accuracy_ — **because it sounds like a weight and names no proportion, no threshold and no number.** **Ask what it would take to show it had been applied; nothing can.**'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** — **an unpublished weighting becomes whatever the assessor felt on the day**, and the two kinds are **a proportion** and **a threshold**, which behave completely differently.'));
out.push(A('**b** **1** ⚠ **They spent fifty minutes of the panel discovering, out loud, that one of their four criteria was worth more to them than the other three put together** — **while assessing, with the candidates in front of them** — **so the weighting was decided by whoever argued best in the room at half past three, and she was one of the two who argued.**   **2** ⚠ **A threshold is a weight where nothing compensates**: _fail this and the others are not read._ **You find out you want one by asking whether brilliance elsewhere would make you accept failure here** — **and a threshold disguised as a proportion is the cruellest page in the unit.**'));
out.push(NOTE('⚠ **The proportion/threshold distinction is the whole cycle and it is the one students collapse.** **A proportion is compensatory**: three weeks on the half can carry a weak quarter. **A threshold is not**: nothing carries it. ⚠ **The diagnostic is one question and it should go on the board in those words** — **would brilliance elsewhere make you accept failure here?** **If the honest answer is no, it is a threshold, whatever number has been written beside it.** **Expect the room to want a middle category** _(a proportion that is a bit of a threshold)_; **there is not one, and the pages that pretend otherwise are the ones that misdirect candidates.**'));
out.push(NOTE('**Rim\'s objection is the real one and it must not be waved away.** ⚠ **Offices resist publishing a weighting because a published weighting can be shown to have been applied — or not to have been.** **That is the cost and it is the point.** **The answer to give the room is the candidate\'s arithmetic:** ⚠ **three weeks on the quarter and four hours on the half.** **She was not outplayed; she was misdirected by a page somebody wrote** — **and no amount of confidentiality makes that fair.** **If a class wants a compromise, the honest one is to publish the weighting and nothing else: not the scores, not the notes, not the ranking.**'));
out.push(S('Language box · Practise'));
out.push(SAMPLE([
  '**1** _(three proportions)_ _The returns count for half; the systems and the visits count for a quarter each._',
  '**2** _(one threshold, two proportions)_ _The safety certificate is a threshold: without it the rest is not read. Price and delivery count for half each._',
  '**3** _(a threshold I had been calling a proportion)_ ⚠ _I had weighted the registered qualification at thirty per cent._ _It is a threshold: unregistered, the rest is not read._',
  '**4** _(said tentatively, to hear it)_ _We would probably say the returns matter most…_ → **and the room reopens it.** _The returns count for half._',
  '**5** _(equal weights)_ _All three count for a third._ ⚠ **Which is a decision**: **it can be shown to have been applied, and _all three will be taken into account_ cannot.**',
]));
out.push(A('⚠ Mark item **3** first and spend the time there: **it is the one that changes a student\'s own page.** About half the room finds a threshold hiding inside a percentage — **a certificate, a registration, an insurance, a seal** — and **every one of those is a thing that cannot be compensated for by anything else on the list.** Item **4** is done aloud or not at all: **the tentative version has to be heard being argued with.**'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**A** _Returns on time / two systems used / four visits a month._',
  '**B** **Returns on time counts for half; the systems and the visits count for a quarter each.** **Thresholds: none.**',
  '**A** _(the ⚠ row)_ _Safety certificate held / price / delivery time._',
  '**B** ⚠ **The safety certificate is a threshold: without it the price and the delivery are not read.** **Price counts for half of the rest and delivery for half.** **It cannot be a proportion** — **no price makes an uncertificated machine acceptable.**',
]));
out.push(S('Stage 3R · Perform – listener task'));
out.push(A('Each weighting, and which weights are thresholds. ⚠ **The four ⚠ rows each hide one thing that cannot be compensated for** — **a safety certificate, a registered qualification, insurance in force, recorded batch numbers** — **and the listener task is the test that catches them.** **A pair that weighted a safety certificate at forty per cent should be asked the question in public:** _what price would make an uncertificated machine acceptable?_ **The silence does the teaching.**'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**a** _**One sentence:** the quarterly returns count for half; the record systems and the site visits count for a quarter each._ ⚠ _**Applying the test:** the returns — yes, brilliance on the visits would make me accept a late return, so it is a proportion. **The systems — no.** **An unregistered system is a thing I cannot accept at any price, and I had written it at twenty-five per cent.** **It is a threshold and I shall publish it as one.**_',
  '**b** _**Tentatively:** we would probably say the returns are the most important of the three._ ⚠ _**Flat:** the returns count for half._ _**My partner said she would argue with the first at half past three and could not see how to argue with the second** — **which is the only difference between them and it is the whole difference.**_',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Three criteria, all failable, and Dima said that if you stop there they are not equal and nobody has said so. On the panel in October they had four criteria and spent fifty minutes discovering, out loud, that one was worth more to them than the other three put together — discovering it while assessing, with the candidates in front of them, which means the weighting was decided by whoever argued best in the room at half past three, and she was one of the two who argued. An unpublished weighting is not absent: it becomes whatever the assessor felt on the day, and it will be felt differently on a Monday and on a Thursday by the same person. Adnan said the fix is one sentence, written before anything is assessed and given to the people being assessed: the returns count for half, the systems and the visits for a quarter each. Twenty words, and it cannot be argued with at half past three because it is already published. Rim asked why give it to the candidates, which her office would resist, and because a weighting they do not know converts their effort into a lottery: a candidate who spends three weeks on the quarter and four hours on the half has not been outplayed, they have been misdirected by a page you wrote. Hiba said that is exactly her forty lessons, and it is, and the weighting is the half of it that 16.1 did not solve. Bassel asked whether all weights are proportions, and no — there are two kinds, a proportion where strength in one compensates for weakness in another, and a threshold where nothing compensates. Omar asked how you know which you want, and you ask whether brilliance elsewhere would make you accept failure here: if the honest answer is no, it is a threshold and must be published as one. A threshold disguised as a proportion is the cruellest page in the unit, because it invites a candidate to compensate for something that cannot be compensated for. And Mazen asked about saying the weights out loud, which is done as a decision already taken, flat, with no hedging round it — the returns count for half, and not we would probably say the returns are the most important. A weight said tentatively is an invitation to reopen it, and somebody always will, usually at half past three.']));
out.push(A('Listener task: the partner\'s weighting and which of their criteria is really a threshold. ⚠ **Collect the thresholds on the board and count them.** **In most rooms between a third and a half of the students find one**, and **almost all of them had written it as a percentage.** **That is the cycle\'s finding and it is worth saying out loud:** **the page was not too vague; it was precise about the wrong thing.**'));
out.push(S('Board clinic – typical mistakes'));
out.push(A('**✗** _All three will be taken into account._ → **✓** a third each, published.   **✗** _We attach particular importance to accuracy._ → **✓** accuracy counts for half.   **✗** A safety certificate at forty per cent. → **✓** a threshold; the rest is not read.   **✗** Deciding the weighting while assessing. → **✓** before, and in public.   **✗** _We shall weight more carefully._ → **✓** a sentence with the weights in it.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** **Published: four criteria, all of them failable** — ⚠ **which was right, and more than they had done the year before.** **Not published: that one of the four mattered more to them than the other three put together.**'));
out.push(A('**2** ⚠ **They said out loud which candidate they would appoint and then worked out what weighting would produce that result.** **She says it is not defensible because it is a weighting decided by two people at half past three on a Thursday** — **and if the same two had been tired, or the other two had argued harder, it would have come out differently.** **Her exact pricing is the line to take:** _that is not corrupt and it is not defensible either._'));
out.push(A('**3** ⚠ **One sentence in the advertisement** — _the handover record counts for half; the three others count for a sixth each_ — **and one threshold published as a threshold:** _without a current certificate the rest is not read._ **The discomfort she expects is a candidate who wins on the arithmetic and whom one of them does not want**: **they must appoint them, or change the weighting in public before the next round and say why** — **and both are harder than October was.**'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**FORTY MINUTES IN JANUARY** · A. Barghouti · 14 March · _for the two of us, before the next tender_',
  '**We spent forty minutes of the January tender meeting discovering what our own criteria were worth.** ⚠ **With three bids on the table and the prices already read out.**',
  '**What we had published.** **Three criteria: price, delivery and the maintenance record.** ⚠ **What we had not published was that the maintenance record would decide it.**',
  '**When we found out.** At about four o\'clock, **with two bids within a hundred thousand of each other.** ⚠ **One was cheap and badly maintained; one was dear and clean.**',
  '**What we did, which was honest and too late.** We named the bid we wanted and then found the weighting that produced it. ⚠ **That is not corrupt and it is not defensible either.**',
  '**What it cost the bidder who lost.** ⚠ **He had cut his price twice and sent nothing about maintenance, because nothing on our page asked him to.** **He had not been outbid. He had been misdirected by a page I wrote.**',
  '**What we shall publish.** _"The maintenance record counts for half; price and delivery for a quarter each."_ ⚠ **And one threshold: _"without a current safety certificate the bid is not read."_**',
  '**And what I expect to be uncomfortable.** ⚠ **The next round will produce a clean, dear bid we cannot afford, and we shall have to take it or change the weighting in public first.**',
]));
out.push(S('Stage 7 · Write freely (sample, 196 words)'));
out.push(SAMPLE([
  '**FIFTY MINUTES IN OCTOBER** · R. Shaaban · 15 March · _for the panel, before the spring round_',
  '**We spent fifty minutes of the October panel deciding, out loud, what our own criteria were worth.** ⚠ **The papers were on the table and the candidates were in the building.**',
  '**What we had published.** **Four criteria, every one of them failable.** ⚠ **What we had not published was that the handover record mattered more to us than the other three put together.**',
  '**When we found out.** At half past three, **with two candidates level on the total** — **one strong on three and weak on the fourth, one the other way round.** ⚠ **The arithmetic made them equal and nobody in the room believed they were.**',
  '**What we did.** We said which one we would appoint and then built the weighting backwards from the answer. ⚠ **That is not corrupt and it is not defensible either.** **It is two tired people at half past three on a Thursday.**',
  '**What it cost the one we did not appoint.** ⚠ **Three weeks on the criterion we weighted at a quarter and an afternoon on the one we weighted at a half.** **She had not been outplayed. She had been misdirected by a page I wrote.**',
  '**What we shall publish.** _The handover record counts for half; the three others for a sixth each._ **And: _without a current certificate the rest is not read._**',
  '**The uncomfortable part.** ⚠ **Spring will hand us a winner one of us does not want, and we shall have to appoint them or change the weighting in public and say why.**',
]));
out.push(A('**196 words, the writer\'s own act named without softening, the cost in the loser\'s units, the weighting printed as a sentence and a threshold beside it, and the discomfort last.** ⚠ **The sentence that earns the band is _built the weighting backwards from the answer_** — **it is the exact thing that happened, it is unflattering, and no page that avoids it can propose a remedy anybody would believe.**'));
out.push(S('Stage 7P · Respond (sample slip — band 2)'));
